import{_ as i,o as r,c as a,a0 as n}from"./chunks/framework.CzVS_xMp.js";const m=JSON.parse('{"title":"Efficient LLM Inference Systems","description":"","frontmatter":{},"headers":[],"relativePath":"inference/efficient-llm-inference-systems/index.md","filePath":"inference/efficient-llm-inference-systems/index.md","lastUpdated":1788490169000}'),t={name:"inference/efficient-llm-inference-systems/index.md"};function o(c,e,s,l,d,f){return r(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="efficient-llm-inference-systems" tabindex="-1">Efficient LLM Inference Systems <a class="header-anchor" href="#efficient-llm-inference-systems" aria-label="Permalink to &quot;Efficient LLM Inference Systems&quot;">​</a></h1><p>This course builds understanding of LLM inference performance metrics and hardware characteristics, and connects KV cache, quantization, and speculative decoding to real measurements. This document guides the overall structure of the course and the appendices; detailed explanations and reference papers are covered in each week&#39;s document.</p><h2 id="curriculum" tabindex="-1">Curriculum <a class="header-anchor" href="#curriculum" aria-label="Permalink to &quot;Curriculum&quot;">​</a></h2><ul><li>[Week 1: Understanding Performance Metrics](week01/ — measures TTFT, TPOT, batch throughput, and memory limits.</li><li>[Week 2: Hardware Foundations for Inference](week02/ — covers the memory hierarchy, Tensor Cores, the roofline model, and inter-GPU communication.</li><li>[Week 3: Transformer Inference and the KV Cache](week03/ — analyzes the memory cost of MHA, MQA, GQA, and MLA for long contexts.</li><li>[Week 4: Quantization](week04/ — compares precision, quantization algorithms, kernel support, and quality/performance trade-offs.</li><li>[Week 5: Speculative Decoding](week05/ — reviews the conditions for latency improvement based on acceptance rate and draft strategies.</li></ul><h2 id="appendix" tabindex="-1">Appendix <a class="header-anchor" href="#appendix" aria-label="Permalink to &quot;Appendix&quot;">​</a></h2><ul><li>[Hardware Architectures for LLM Inference](appendix/hardware-architectures/</li><li>[LLM Inference](appendix/llm-inference/</li><li>[Transformer](appendix/transformer/</li></ul><h2 id="source-material" tabindex="-1">Source Material <a class="header-anchor" href="#source-material" aria-label="Permalink to &quot;Source Material&quot;">​</a></h2><ul><li><a href="https://drive.google.com/file/d/1mfTzOnwn8yx4eKObjPvpd-B_toGkQ_tu/view" target="_blank" rel="noreferrer">Efficient LLM Inference Systems, Algorithms &amp; Production Engineering — Interview Pocket Notes</a> (2026)</li></ul><h2 id="related-topics" tabindex="-1">Related Topics <a class="header-anchor" href="#related-topics" aria-label="Permalink to &quot;Related Topics&quot;">​</a></h2><ul><li>[SGLang Production Practices](../sglang-production-practices/ — connects KV cache, speculative decoding, routing, and distributed topology to production SLOs.</li><li>[Model Architecture and Serving Profiles](../models/ — organizes per-model architecture and serving characteristics.</li><li>[FlashAttention from First Principles](../flashattention-from-first-principles/ (<a href="./../flashattention-from-first-principles/README.ko">English edition</a>) — explains I/O-aware kernel optimization for exact attention.</li></ul>',10)])])}const p=i(t,[["render",o]]);export{m as __pageData,p as default};
